namespace LocalSpt5Esp;
internal static class TeleportControl {
 sealed record Destination(string Key,string Name,string Detail,Vector3 Position,LiveActorReference? Actor=null,string Loot="",string Exit="");
 static readonly string[] tabs={"高价值房间","钥匙房","撤离点","传送到 AI","物品","收藏点","坐标","AI 互传"};
 static readonly int[] tabOrder={7,0,1,2,3,4,5,6};
 internal static string LastNotice=>notice;
 static readonly List<TeleportMapPoint> mapPoints=new();static readonly List<SavedTeleportPoint> saved=new();static readonly List<Destination> destinations=new();static readonly List<LiveActorReference> sources=new();
 static readonly Dictionary<string,List<Door>> doors=new();static IntPtr world;static int page;static bool loaded,corrupt,safe=true,useAiSources,allSavedMaps;static float nextList,nextDoors;static Vector2 scroll;static string query="",lastQuery="\0",notice="",x="0",y="0",z="0",pointName="",pointMap="",editId="";static int environmentMask;
 static string FilePath=>Path.Combine(BepInEx.Paths.PluginPath,"LocalSpt5ESP","teleport-points.json");
 internal static bool WantsExitData=>InterfaceMenu.TeleportPage||InterfaceMenu.AiPage;
 static string Map=>TeleportRules.Map(Singleton<GameWorld>.Instance?.LocationId??"");
 static NVector N(Vector3 p)=>new(p.x,p.y,p.z);static Vector3 U(NVector p)=>new(p.X,p.Y,p.Z);
 static void Load(){if(loaded)return;loaded=true;var errors=new List<string>();mapPoints.AddRange(TeleportRules.ReadMapDirectory(Path.Combine(BepInEx.Paths.PluginPath,"mpstark-dynamicmaps","Maps"),errors));foreach(var error in errors)Plugin.Self.Log.LogWarning("Teleport map data: "+error);try{var points=PresetStorage.Load<SavedTeleportPoint>(FilePath);foreach(var point in points)TeleportRules.Validate(point);if(points.Select(point=>point.Id).Distinct().Count()!=points.Count)throw new InvalidDataException("收藏点编号重复。");saved.AddRange(points);}catch(Exception e){corrupt=true;notice="传送点文件读取失败，原文件保留："+e.Message;}Plugin.Self.Log.LogInfo("Teleport catalog ready: "+mapPoints.Count+" map room entrances and "+saved.Count+" saved points");}
 internal static void Reset(){AiPairTransfer.Reset();world=IntPtr.Zero;doors.Clear();sources.Clear();destinations.Clear();useAiSources=false;nextList=nextDoors=0;}
 internal static void Tick(GameWorld? current){if(current==null){if(world!=IntPtr.Zero)Reset();return;}if(world!=current.Pointer){Reset();world=current.Pointer;pointMap=TeleportRules.Map(current.LocationId??"");}}
 static GameWorld Current(){var current=Singleton<GameWorld>.Instance;if(!RaidClock.Active||current==null||current.Pointer!=world)throw new ArgumentException("请在当前战局内传送。");return current;}
 internal static void SetAiSources(GameWorld current,IEnumerable<Player> actors){Tick(current);sources.Clear();foreach(var actor in actors)if(actor.IsAI&&!actor.IsYourPlayer)sources.Add(new(current,actor));useAiSources=true;nextList=0;}
 static Player[] Moving(){var current=Current();if(!useAiSources)return new[]{current.MainPlayer??throw new ArgumentException("本地玩家尚未就绪。")};if(sources.Count==0)throw new ArgumentException("先在 AI 管理多选来源 AI。");return sources.Select(reference=>reference.Resolve()).ToArray();}
 static void ScanDoors(){doors.Clear();foreach(var door in Object.FindObjectsOfType<Door>())if(door!=null&&!string.IsNullOrWhiteSpace(door.KeyId)){if(!doors.TryGetValue(door.KeyId,out var group)){group=new();doors[door.KeyId]=group;}group.Add(door);}}
 static Vector3 RoomPosition(TeleportMapPoint point){var fallback=U(point.Position);if(point.Key.Length>0&&doors.TryGetValue(point.Key,out var candidates)){var closest=candidates.Where(d=>d!=null).OrderBy(d=>(d.transform.position-fallback).sqrMagnitude).FirstOrDefault();if(closest!=null&&(closest.transform.position-fallback).sqrMagnitude<144)return closest.transform.position;}return fallback;}
 static void Refresh(bool full=false){Load();destinations.Clear();var current=Singleton<GameWorld>.Instance;var player=current?.MainPlayer;if(RaidClock.Active&&(full||Time.unscaledTime>=nextDoors)){ScanDoors();nextDoors=Time.unscaledTime+30;}if(page is 0 or 1){foreach(var point in mapPoints.Where(p=>TeleportRules.SameMap(p.Map,Map)&&(page==1||p.Popular)))destinations.Add(new("room:"+point.Id,point.Name,point.Key.Length>0?ItemSpawner.TemplateName(point.Key)+" · 房间入口附近":"房间入口附近",RoomPosition(point)));if(page==1)foreach(var pair in doors)foreach(var door in pair.Value){if(door==null)continue;var position=door.transform.position;if(destinations.Any(item=>(item.Position-position).sqrMagnitude<4))continue;destinations.Add(new("door:"+door.Pointer,ItemSpawner.TemplateName(pair.Key),"当前地图实时门点",position));}}
  else if(page==2)foreach(var exit in ExfilDisplay.NavigationRows)destinations.Add(new("exit:"+exit.Id,exit.Name,exit.State+(exit.Available?" · 本局可用":" · 本局条件未满足"),exit.Position,Exit:exit.Id));
  else if(page==3&&current?.AllAlivePlayersList!=null){var list=current.AllAlivePlayersList;for(int i=0;i<list.Count;i++){var actor=list[i];if(actor?.IsAI!=true||actor.IsYourPlayer||actor.HealthController?.IsAlive!=true)continue;var reference=new LiveActorReference(current,actor);destinations.Add(new("ai:"+actor.ProfileId,reference.Name,actor.AIData?.BotOwner is BotOwner bot?AiActorControl.Team(bot):"AI",actor.Position,reference));}}
  else if(page==4)foreach(var item in RaidLoot.TeleportEntries)destinations.Add(new("loot:"+item.Key,item.Name,item.Source+" · 估值 "+item.Value.ToString("N0",CultureInfo.InvariantCulture),item.Position,Loot:item.Key));
  else if(page==5)foreach(var point in saved.Where(p=>allSavedMaps||!RaidClock.Active||TeleportRules.SameMap(p.Map,Map)))destinations.Add(new("saved:"+point.Id,point.Name,TeleportRules.MapName(point.Map)+" · "+U(point.Position).ToString("F2"),U(point.Position)));
  var origin=player?.Position??Vector3.zero;var filtered=destinations.Where(item=>(item.Name+" "+item.Detail).Contains(query,StringComparison.OrdinalIgnoreCase)).OrderBy(item=>(item.Position-origin).sqrMagnitude).ToArray();destinations.Clear();destinations.AddRange(filtered);nextList=Time.unscaledTime+1;lastQuery=query;
 }
 static bool Occupied(Vector3 point,Player moving,List<Vector3> reserved){float radius=Math.Max(.25f,moving.CharacterController?.radius??.3f);if(reserved.Any(position=>new Vector2(position.x-point.x,position.z-point.z).sqrMagnitude<(radius*2+.3f)*(radius*2+.3f)&&Math.Abs(position.y-point.y)<1.7f))return true;var list=Singleton<GameWorld>.Instance?.AllAlivePlayersList;if(list!=null)for(int i=0;i<list.Count;i++){var actor=list[i];if(actor==null||actor.Pointer==moving.Pointer||actor.HealthController?.IsAlive!=true)continue;var p=actor.Position;if(Math.Abs(p.y-point.y)<1.7f&&new Vector2(p.x-point.x,p.z-point.z).sqrMagnitude<1.2f)return true;}return false;}
 static Vector3 Landing(Player actor,Vector3 goal,bool nearActor,List<Vector3> reserved){if(!TeleportRules.Finite(N(goal)))throw new ArgumentException("目标坐标无效。");if(!safe&&actor.IsYourPlayer&&!nearActor&&reserved.Count==0)return goal;if(environmentMask==0)environmentMask=LayerMask.GetMask("HighPolyCollider","Terrain","LowPolyCollider");if(environmentMask==0)throw new InvalidOperationException("碰撞层尚未就绪。");var candidates=new List<Vector3>();if(!nearActor)candidates.Add(goal);int rings=Math.Max(3,(int)Math.Ceiling(Math.Sqrt(reserved.Count+1))+1);for(int ring=0;ring<rings;ring++){float radius=nearActor?2+ring*1.6f:1+ring*1.3f;for(int i=0;i<12;i++){float angle=i*Mathf.PI/6;candidates.Add(goal+new Vector3(Mathf.Cos(angle)*radius,0,Mathf.Sin(angle)*radius));}}
  var controller=Singleton<AbstractGame>.Instance?.TryCast<IBotGame>()?.BotsController;foreach(var candidate in candidates){Vector3 point;if(NavMesh.SamplePosition(candidate,out var nav,2f,NavMesh.AllAreas)&&Math.Abs(nav.position.y-goal.y)<=2)point=nav.position;else if(actor.IsYourPlayer&&Physics.Raycast(candidate+Vector3.up*1.8f,Vector3.down,out var floor,3.8f,environmentMask,QueryTriggerInteraction.Ignore)&&floor.normal.y>.5f)point=floor.point;else continue;if(!actor.IsYourPlayer&&!AiLimitCompatibility.HasNavigation(controller?.CoversData,point))continue;float radius=Math.Max(.22f,actor.CharacterController?.radius??.3f),height=Math.Max(radius*2+.1f,actor.CharacterController?.height??1.75f);if(Physics.CheckCapsule(point+Vector3.up*(radius+.12f),point+Vector3.up*(height-radius),radius,environmentMask,QueryTriggerInteraction.Ignore)||Occupied(point,actor,reserved))continue;return point+Vector3.up*.05f;}throw new ArgumentException("目标附近没有可用落点。");}
 static void Move(Player actor,Vector3 point){if(actor.IsYourPlayer){actor.Teleport(point,true);return;}var owner=actor.AIData?.BotOwner??throw new ArgumentException("AI 控制器未就绪。");var controller=Singleton<AbstractGame>.Instance?.TryCast<IBotGame>()?.BotsController;var covers=controller?.CoversData;if(!AiLimitCompatibility.HasNavigation(covers,point))throw new ArgumentException("AI 无法站在该位置，请更换落点。");if(owner.VoxelesPersonalData!=null&&(owner.VoxelesPersonalData._data==null||owner.VoxelesPersonalData._data.VoxelesArray==null))owner.VoxelesPersonalData.Activate(covers);AiLimitCompatibility.Wake(actor);owner.StopMove();owner.Mover?.AllowTeleport();bool moved=owner.Mover?.Teleport(point,true)==true;if(!moved||Vector3.Distance(actor.Position,point)>2)controller?.DevelopmentTeleportBot(owner,point);if(Vector3.Distance(actor.Position,point)>2)throw new InvalidOperationException("AI 传送未能完成，请尝试更换落点。");owner.Mover?.RecalcWay();}
 static void Execute(Destination destination){var moving=Moving();Vector3 goal=destination.Position;bool near=destination.Actor!=null;if(destination.Actor!=null){var target=destination.Actor.Resolve();if(moving.Any(actor=>actor.Pointer==target.Pointer))throw new ArgumentException("目标 AI 也在来源列表中，请从来源中取消选择它。");goal=target.Position;}if(destination.Loot.Length>0&&!RaidLoot.TryTeleportTarget(destination.Loot,out goal,out _))throw new ArgumentException("物品已被拿走、销毁或离开原容器，请刷新列表。");if(destination.Exit.Length>0){if(!ExfilDisplay.TryNavigationExit(destination.Exit,out var exit)||exit==null)throw new ArgumentException("撤离点已失效。");goal=exit.Position;}if(destination.Key.StartsWith("saved:",StringComparison.Ordinal)){var point=saved.FirstOrDefault(p=>"saved:"+p.Id==destination.Key)??throw new ArgumentException("收藏点已删除。");if(!TeleportRules.SameMap(point.Map,Map))throw new ArgumentException("该收藏点属于其他地图。");}
  var planned=new List<(Player Actor,Vector3 Position)>();var reserved=new List<Vector3>();foreach(var actor in moving){var position=Landing(actor,goal,near,reserved);planned.Add((actor,position));reserved.Add(position);}int complete=0;foreach(var plan in planned){new LiveActorReference(Current(),plan.Actor).Resolve();Move(plan.Actor,plan.Position);if(Vector3.Distance(plan.Actor.Position,plan.Position)>2)throw new InvalidOperationException("已完成 "+complete+" 个传送，后续位置回读不一致。");complete++;}notice="已传送 "+complete+" 个角色至 "+destination.Name+" 附近。";FeatureToasts.Show(notice);}
 static void Action(Action action){try{action();}catch(Exception e){notice=e.Message;FeatureToasts.Show(e.Message);Plugin.Self.Log.LogWarning("Teleport control: "+e.Message);}}
 internal static void ToLoot(string key){Action(()=>{Tick(Singleton<GameWorld>.Instance);useAiSources=false;if(!RaidLoot.TryTeleportTarget(key,out var point,out var name))throw new ArgumentException("物品已离开原位置。");Execute(new("loot:"+key,name,"",point,Loot:key));});}
 internal static void PlayerToAi(Player target){Action(()=>{var current=Current();useAiSources=false;Execute(new("ai:"+target.ProfileId,target.Profile?.Nickname??"AI","",target.Position,new(current,target)));});}
 internal static void AiToPlayer(IEnumerable<Player> actors){Action(()=>{var current=Current();SetAiSources(current,actors);var target=current.MainPlayer??throw new ArgumentException("玩家尚未就绪。");Execute(new("player","玩家","",target.Position,new(current,target)));});}
 internal static void AiToAi(IEnumerable<LiveActorReference> references,LiveActorReference destination){Action(()=>{Tick(Singleton<GameWorld>.Instance);var current=Current();var moving=references.Select(reference=>reference.Resolve()).ToArray();var target=destination.Resolve();if(moving.Length==0)throw new ArgumentException("请先选择来源 AI。");if(!target.IsAI||target.IsYourPlayer||moving.Any(actor=>actor.Pointer==target.Pointer))throw new ArgumentException("来源和目标需要是不同的 AI。");SetAiSources(current,moving);Execute(new("ai:"+target.ProfileId,destination.Name,"",target.Position,destination));});}
 static void CapturePosition(){var player=Current().MainPlayer??throw new ArgumentException("玩家尚未就绪。");x=player.Position.x.ToString("G9",CultureInfo.InvariantCulture);y=player.Position.y.ToString("G9",CultureInfo.InvariantCulture);z=player.Position.z.ToString("G9",CultureInfo.InvariantCulture);pointMap=Map;}
 static void SavePoint(bool copy){Load();if(corrupt)throw new ArgumentException("请先修复收藏点文件。");string name=TeleportRules.Name(pointName),map=TeleportRules.Map(pointMap);if(map.Length==0)throw new ArgumentException("请填写地图 或进入战局后获取。");var point=TeleportRules.Coordinates(x,y,z);var savedPoint=new SavedTeleportPoint{Id=copy||editId.Length==0?Guid.NewGuid().ToString("N"):editId,Name=name,Map=map,X=point.X,Y=point.Y,Z=point.Z};var next=saved.Where(p=>p.Id!=savedPoint.Id).Append(savedPoint).ToList();TeleportRules.Validate(savedPoint);PresetStorage.Save(FilePath,next);saved.Clear();saved.AddRange(next);editId=savedPoint.Id;notice="已保存传送点："+name;nextList=0;}
 static void LoadPoint(string id){var point=saved.First(p=>p.Id==id);x=point.X.ToString("G9",CultureInfo.InvariantCulture);y=point.Y.ToString("G9",CultureInfo.InvariantCulture);z=point.Z.ToString("G9",CultureInfo.InvariantCulture);pointName=point.Name;pointMap=point.Map;editId=point.Id;page=6;nextList=0;}
 static void DeletePoint(string id){if(corrupt)throw new ArgumentException("收藏点文件读取失败，未覆盖。");var next=saved.Where(p=>p.Id!=id).ToList();PresetStorage.Save(FilePath,next);saved.Clear();saved.AddRange(next);if(editId==id)editId="";nextList=0;notice="收藏点已删除。";}
 internal static void DrawActorTools(Rect rect,IEnumerable<Player> actors){Load();Tick(Singleton<GameWorld>.Instance);var list=actors.ToArray();float x=rect.x,y=rect.y,w=rect.width;float col=(w-20)/3;if(InterfaceMenu.Button(new Rect(x,y,col,36),list.Length==1?"玩家 → 当前 AI":"玩家 → 第一名所选 AI")&&list.Length>0)PlayerToAi(list[0]);if(InterfaceMenu.Button(new Rect(x+col+10,y,col,36),"所选 AI → 玩家"))AiToPlayer(list);if(InterfaceMenu.Button(new Rect(x+2*(col+10),y,col,36),"房间／物品等目标")){Action(()=>{SetAiSources(Current(),list);InterfaceMenu.ShowTeleport();page=0;query="";nextList=0;});}y+=52;AiPairTransfer.Draw(new Rect(x,y,w,rect.yMax-y));}
 internal static void Draw(Rect rect){Load();Tick(Singleton<GameWorld>.Instance);float x0=rect.x,y0=rect.y,w=rect.width;InterfaceMenu.Label(new Rect(x0,y0,w-140,30),"传送",InterfaceMenu.Accent,20);if(InterfaceMenu.Button(new Rect(x0+w-132,y0,132,30),"刷新地图目标"))Action(()=>Refresh(true));y0+=44;float cell=(w-18)/4;for(int slot=0;slot<tabOrder.Length;slot++){int i=tabOrder[slot];if(InterfaceMenu.Button(new Rect(x0+slot%4*(cell+6),y0+slot/4*38,cell,32),tabs[i],page==i)){page=i;scroll=Vector2.zero;nextList=0;}}y0+=86;if(page==7){AiPairTransfer.Draw(new Rect(x0,y0,w,rect.yMax-y0));return;}InterfaceMenu.Label(new Rect(x0,y0,72,34),"传送角色",null,13);float sourceWidth=(w-92)/2;if(InterfaceMenu.Button(new Rect(x0+84,y0,sourceWidth,34),"玩家",!useAiSources))useAiSources=false;bool wasEnabled=GUI.enabled;GUI.enabled=wasEnabled&&sources.Count>0;if(InterfaceMenu.Button(new Rect(x0+92+sourceWidth,y0,sourceWidth,34),"所选 AI（"+sources.Count+"）",useAiSources))useAiSources=true;GUI.enabled=wasEnabled;y0+=46;if(InterfaceMenu.Button(new Rect(x0,y0,w,30),safe?"安全落点检查 · 开启":"安全落点检查 · 关闭（仅玩家坐标直传）",safe))safe=!safe;y0+=42;
  if(page==6){float top=y0;InterfaceMenu.Paragraph(new Rect(x0,top,w,40),"输入 X、Y、Z 坐标；Y 为高度。",null,12);top+=48;float third=(w-16)/3;string Coordinate(string label,string value,float left){InterfaceMenu.Label(new Rect(left,top,third,22),label,null,12);return InterfaceMenu.Field(new Rect(left,top+27,third,34),value);}x=Coordinate("X",x,x0);y=Coordinate("Y（高度）",y,x0+third+8);z=Coordinate("Z",z,x0+2*(third+8));top+=78;
   if(InterfaceMenu.Button(new Rect(x0,top,(w-12)/2,36),"读取玩家当前位置"))Action(CapturePosition);if(InterfaceMenu.Button(new Rect(x0+(w+12)/2,top,(w-12)/2,36),"传送到坐标"))Action(()=>{var point=TeleportRules.Coordinates(x,y,z);Execute(new("coordinate","指定坐标","",U(point)));});top+=54;
   InterfaceMenu.Label(new Rect(x0,top,w*.46f,23),"地图内部 ID",null,12);InterfaceMenu.Label(new Rect(x0+w*.49f,top,w*.51f,23),"传送点名称",null,12);if(InterfaceMenu.Button(new Rect(x0,top+28,w*.46f,34),TeleportRules.MapName(pointMap))){var maps=mapPoints.Select(p=>p.Map).Concat(saved.Select(p=>p.Map)).Append(Map).Where(p=>p.Length>0).Distinct().OrderBy(p=>p).ToArray();if(maps.Length>0)pointMap=maps[(Array.IndexOf(maps,pointMap)+1)%maps.Length];}pointName=InterfaceMenu.Field(new Rect(x0+w*.49f,top+28,w*.51f,34),pointName);top+=82;
   if(InterfaceMenu.Button(new Rect(x0,top,(w-12)/2,38),editId.Length>0?"保存所选点修改":"保存坐标点"))Action(()=>SavePoint(false));if(InterfaceMenu.Button(new Rect(x0+(w+12)/2,top,(w-12)/2,38),"新增／另存为传送点"))Action(()=>SavePoint(true));top+=56;InterfaceMenu.Paragraph(new Rect(x0,top,w,62),editId.Length>0?"正在编辑已保存的传送点；“另存为”会保留原点并创建新点。":"可以保存多个点，重新启动后保留。",null,12);
  }else{if(page==5){if(InterfaceMenu.Button(new Rect(x0,y0,w,30),allSavedMaps?"显示所有地图收藏点":"只显示当前地图收藏点")){allSavedMaps=!allSavedMaps;nextList=0;}y0+=40;}query=InterfaceMenu.Field(new Rect(x0,y0,w,31),query);y0+=43;if(Time.unscaledTime>=nextList||query!=lastQuery)Action(()=>Refresh());var origin=Singleton<GameWorld>.Instance?.MainPlayer?.Position??Vector3.zero;var filtered=destinations;var view=new Rect(x0,y0,w,Math.Max(70,rect.yMax-y0-72));scroll=GUI.BeginScrollView(view,scroll,new Rect(0,0,w-20,Math.Max(view.height-1,filtered.Count*108)));int first=Math.Max(0,(int)(scroll.y/108)),end=Math.Min(filtered.Count,first+(int)Math.Ceiling(view.height/108)+2);Destination? execute=null,edit=null;string? remove=null;for(int i=first;i<end;i++){var item=filtered[i];float top=i*108;InterfaceMenu.Surface(new Rect(0,top,w-26,100),Color.Lerp(InterfaceMenu.Background,InterfaceMenu.Text,.04f),9);InterfaceMenu.Paragraph(new Rect(12,top+8,w-200,75),item.Name+"\n"+item.Detail+"\n距离 "+Vector3.Distance(origin,item.Position).ToString("F0")+" 米",null,12);if(InterfaceMenu.Button(new Rect(w-170,top+10,126,32),"传送到这里"))execute=item;if(InterfaceMenu.Button(new Rect(w-170,top+51,126,30),page==5?"编辑坐标":"坐标／收藏"))edit=item;if(page==5&&InterfaceMenu.Button(new Rect(w-275,top+62,90,26),"删除点"))remove=item.Key[6..];}if(filtered.Count==0)InterfaceMenu.Paragraph(new Rect(12,10,w-44,68),page==4?"暂无物品条目；先在“本局物品”开启扫描。":page is 0 or 1?"当前地图暂无对应目录；进入战局后刷新，可补充实时门点。":"暂无目标；进入战局或先保存自定义点。",null,13);GUI.EndScrollView();if(execute!=null)Action(()=>Execute(execute));if(edit!=null)Action(()=>{if(edit.Key.StartsWith("saved:",StringComparison.Ordinal))LoadPoint(edit.Key[6..]);else{var point=edit.Position;x=point.x.ToString("G9",CultureInfo.InvariantCulture);y=point.y.ToString("G9",CultureInfo.InvariantCulture);z=point.z.ToString("G9",CultureInfo.InvariantCulture);pointMap=Map;pointName=edit.Name;editId="";page=6;}});if(remove!=null)Action(()=>DeletePoint(remove));}
  InterfaceMenu.Paragraph(new Rect(x0,rect.yMax-62,w,58),notice.Length>0?notice:"房间落点在入口附近。",InterfaceMenu.Accent,12);
 }
